const p = msg.payload;
if (!p || typeof p !== 'object') {
    node.error('Payload MQTT não é um objeto JSON', msg);
    return null;
}

const deviceId = String(p.device_id || '').trim();
const temp = Number(p.temp);
const humidity = Number(p.umid);
const heatIndex = p.ic === undefined || p.ic === null ? null : Number(p.ic);
const rssi = p.rssi === undefined || p.rssi === null ? null : Number(p.rssi);

if (!/^[a-zA-Z0-9_-]{1,64}$/.test(deviceId)) {
    node.error('device_id ausente ou inválido', msg);
    return null;
}
if (!Number.isFinite(temp) || temp < -40 || temp > 80) {
    node.error('temperatura fora da faixa válida', msg);
    return null;
}
if (!Number.isFinite(humidity) || humidity < 0 || humidity > 100) {
    node.error('umidade fora da faixa válida', msg);
    return null;
}
if (heatIndex !== null && !Number.isFinite(heatIndex)) {
    node.error('índice de calor inválido', msg);
    return null;
}
if (rssi !== null && (!Number.isFinite(rssi) || rssi < -120 || rssi > 0)) {
    node.error('RSSI fora da faixa válida', msg);
    return null;
}

// O nó InfluxDB escapa tags e fields e recebe o measurement da própria configuração.
const fields = { temperatura: temp, umidade: humidity };
if (heatIndex !== null) fields.indice_calor = heatIndex;
if (rssi !== null) fields.rssi = rssi;
const tags = { device_id: deviceId, sensor: String(p.sensor || 'legacy') };

node.status({ fill: 'green', shape: 'dot', text: `${deviceId}: ${temp} °C / ${humidity} %` });

// Saída 1 grava no InfluxDB; saída 2 leva uma cópia própria ao Zabbix.
return [
    { ...msg, payload: [fields, tags] },
    { ...msg, payload: { ...fields } }
];

// As chaves são os itens trapper do host definido em ZABBIX_HOST_NAME
// (campo "Default hostname" do nó zabbix-sender). Itens ausentes são omitidos.
const medicao = msg.payload;
const itens = [
    ['temperatura', medicao.temperatura],
    ['umidade', medicao.umidade],
    ['indice_calor', medicao.indice_calor],
    ['rssi', medicao.rssi]
].filter(([, valor]) => valor !== undefined && valor !== null)
 .map(([chave, valor]) => [chave, String(valor)]);

if (itens.length === 0) {
    node.error('Nenhum item válido para enviar ao Zabbix', msg);
    return null;
}

node.status({ fill: 'green', shape: 'dot', text: `${itens.length} itens` });
msg.payload = itens;
return msg;
